package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code possibleDuplicate} / {@code possibleDuplicateOf}: a soft-match
 * flag for a new owner that is not a hard duplicate but still looks like one.
 *
 * <p>A create is only rejected (409) when the new owner's whole {@code identityKey} equals an
 * existing owner's (see {@link RequireUniqueIdentity}), so by the time this step runs the new
 * owner is guaranteed not to be a hard duplicate. Here we flag the weaker signal: an existing
 * owner that shares the same {@code lastName} (compared case-insensitively) and the same
 * {@code postcode}. When one is found the owner is still created, but with
 * {@code possibleDuplicate} true and {@code possibleDuplicateOf} set to the (lowest) matching
 * owner id; otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is
 * left unset.
 *
 * <p>Runs after {@link BuildOwner} (so the owner's fields are set) and before
 * {@link SaveOwner} (so the new owner is not compared against itself).
 */
public class AssignPossibleDuplicate {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String lastName = owner.getLastName();
        String postcode = owner.getPostcode();
        Integer matchId = null;
        if (lastName != null && postcode != null && !postcode.isBlank()) {
            for (Owner existing : ownerRepository.findAll()) {
                if (lastName.equalsIgnoreCase(existing.getLastName())
                        && postcode.equals(existing.getPostcode())
                        && (matchId == null || existing.getId() < matchId)) {
                    matchId = existing.getId();
                }
            }
        }
        owner.setPossibleDuplicate(matchId != null);
        owner.setPossibleDuplicateOf(matchId);
    }
}

